// probes/powerups/retail-placement.mjs
// Generated by probes/powerups/tools/build_retail_placement.mjs from
// probes/powerups/tools/retail_placement_module.template.mjs and
// probes/powerups/data/retail-placement.json. Do not edit by hand.
//
// Browser-importable retail pickup placement for the e1-drive power-up slice.
//
// Contract:
//   import { RETAIL_PLACEMENT_SCHEMA, retailPlacementsFor } from './retail-placement.mjs';
//   const set = retailPlacementsFor('amboy', layout);
//   // layout is the measured layout the page drives:
//   //   { course: { lengthMetres, band|corridor, samples: [{arc,x,z,groundY}, ...] } }
//
// Rule: `f = retail.arc / retail.routeLengthM`, then the measured layout is
// sampled at `f` (nearest committed sample, ties to the earlier sample). The
// retail lateral is kept when it fits inside the measured band; otherwise it is
// clamped to the band and `clamped: true` is recorded with the applied value.
// This is a project placement rule, not a physical projection: the measured
// layout is a sub-course of the retail route and its arc origin is not the
// retail origin. The committed source data records those offsets under
// `soundness`.
//
// `pickups[]` carries the applied measured `arc`, `lateral`, `x/y/z`, the retail
// `route`, and a `source` string naming the retail uid, route and rule.
// `unsupported[]` carries every retail uid that could not be projected.

export const RETAIL_PLACEMENT_SCHEMA = 'blur.powerups-retail-placement/1';

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function fail(message) {
  throw new Error('retail-placement: ' + message);
}

function round6(value) {
  const rounded = Math.round(value * 1e6) / 1e6;
  return Object.is(rounded, -0) ? 0 : rounded;
}

function round9(value) {
  const rounded = Math.round(value * 1e9) / 1e9;
  return Object.is(rounded, -0) ? 0 : rounded;
}

/** The measured band is the declared respawn/controller band of the layout. */
function bandOf(layout) {
  const band = layout?.course?.band?.halfWidthMetres;
  if (Number.isFinite(band) && band > 0) {
    return { halfWidthMetres: band, source: 'course.band.halfWidthMetres' };
  }
  const corridor = layout?.course?.corridor?.halfWidthMetres;
  if (Number.isFinite(corridor) && corridor > 0) {
    return { halfWidthMetres: corridor, source: 'course.corridor.halfWidthMetres' };
  }
  return null;
}

function measuredLengthOf(layout) {
  const length = layout?.course?.lengthMetres;
  if (Number.isFinite(length) && length > 0) return length;
  const samples = layout?.course?.samples;
  if (Array.isArray(samples) && samples.length > 0) {
    const last = samples[samples.length - 1];
    if (Number.isFinite(last?.arc) && last.arc > 0) return last.arc;
  }
  return null;
}

/** Nearest committed sample; ties go to the earlier sample. */
function nearestSample(samples, targetArc) {
  let bestIndex = 0;
  let bestDelta = Math.abs((samples[0].arc ?? 0) - targetArc);
  for (let index = 1; index < samples.length; index++) {
    const delta = Math.abs((samples[index].arc ?? 0) - targetArc);
    if (delta < bestDelta) {
      bestIndex = index;
      bestDelta = delta;
    }
  }
  return { index: bestIndex, sample: samples[bestIndex], delta: bestDelta };
}

/** Unit left normal (-tz, tx) of the measured polyline at a sample. */
function leftNormalAt(samples, index) {
  const a = samples[Math.max(0, index - 1)];
  const b = samples[Math.min(samples.length - 1, index + 1)];
  const tx = (b.x ?? 0) - (a.x ?? 0);
  const tz = (b.z ?? 0) - (a.z ?? 0);
  const length = Math.hypot(tx, tz);
  if (!(length > 0)) return { x: 0, z: 0 };
  return { x: -tz / length, z: tx / length };
}

export const RETAIL_PLACEMENT_DATA = deepFreeze(/*__RETAIL_PLACEMENT_DATA__*/);

/**
 * Place the retail pickups of a map on the measured layout the page drives.
 *
 * @param {'amboy'|'gracia'|'river'} mapId
 * @param {{course:{lengthMetres:number,band?:{halfWidthMetres:number},
 *   corridor?:{halfWidthMetres:number},samples:Array<{arc:number,x:number,z:number,groundY?:number}>}}} layout
 * @returns {{schema:string, mapId:string, source:string,
 *   pickups:Array<{id:string,uid:number,type:string,x:number,y:number,z:number,
 *     arc:number,lateral:number,retailLateral:number,clamped:boolean,
 *     clampedBy:number,fraction:number,route:string,routeIndex:number,
 *     retailArc:number,routeLengthM:number,sampleIndex:number,source:string}>,
 *   unsupported:Array<{id:string,uid:number,type:string,reason:string}>}}
 */
export function retailPlacementsFor(mapId, layout) {
  const map = RETAIL_PLACEMENT_DATA.maps[mapId];
  if (!map) {
    fail('unknown map ' + JSON.stringify(mapId) + ' (use ' +
      Object.keys(RETAIL_PLACEMENT_DATA.maps).join(', ') + ')');
  }
  const samples = layout?.course?.samples;
  const band = bandOf(layout);
  const measuredLength = measuredLengthOf(layout);
  const measuredLengthText = Number.isFinite(measuredLength)
    ? measuredLength.toFixed(6)
    : 'n/a';
  const layoutId = layout?.courseId ?? layout?.course?.name ?? map.measuredLayout.id;
  const pickups = [];
  const unsupported = [];

  for (const row of map.pickups) {
    const id = mapId + ':' + row.uid;
    if (!Number.isFinite(row.arc) || !Number.isFinite(row.routeLengthM) || !(row.routeLengthM > 0)) {
      unsupported.push({
        id,
        uid: row.uid,
        type: row.type,
        reason: 'no-route-arc: retail arc ' + row.arc + ' m / route length ' +
          row.routeLengthM + ' m is not a finite positive arc'
      });
      continue;
    }
    if (!Array.isArray(samples) || samples.length === 0) {
      unsupported.push({
        id,
        uid: row.uid,
        type: row.type,
        reason: 'no-measured-sample: layout.course.samples is empty'
      });
      continue;
    }
    if (!band) {
      fail('layout has neither course.band.halfWidthMetres nor ' +
        'course.corridor.halfWidthMetres; the retail lateral cannot be clamped');
    }
    if (!(measuredLength > 0)) {
      fail('layout has no positive course.lengthMetres or sample arc');
    }
    const fraction = row.arc / row.routeLengthM;
    if (!(fraction >= 0 && fraction <= 1)) {
      unsupported.push({
        id,
        uid: row.uid,
        type: row.type,
        reason: 'arc-outside-route: retail arc ' + row.arc.toFixed(6) +
          ' m is outside route length ' + row.routeLengthM.toFixed(6) + ' m'
      });
      continue;
    }

    const targetArc = fraction * measuredLength;
    const hit = nearestSample(samples, targetArc);
    const normal = leftNormalAt(samples, hit.index);
    const retailLateral = row.lateral;
    const clamped = Math.abs(retailLateral) > band.halfWidthMetres;
    const appliedLateral = clamped
      ? Math.sign(retailLateral) * band.halfWidthMetres
      : retailLateral;
    const sampleArc = hit.sample.arc ?? targetArc;
    const x = (hit.sample.x ?? 0) + normal.x * appliedLateral;
    const z = (hit.sample.z ?? 0) + normal.z * appliedLateral;
    const y = hit.sample.groundY ?? hit.sample.height ?? 0;

    pickups.push({
      id,
      uid: row.uid,
      type: row.type,
      x: round6(x),
      y: round6(y),
      z: round6(z),
      arc: round6(sampleArc),
      lateral: round6(appliedLateral),
      retailLateral: round6(retailLateral),
      clamped,
      clampedBy: round6(Math.max(0, Math.abs(retailLateral) - band.halfWidthMetres)),
      fraction: round9(fraction),
      route: row.route,
      routeIndex: row.routeIndex,
      retailArc: round6(row.arc),
      routeLengthM: round6(row.routeLengthM),
      sampleIndex: hit.index,
      source: 'retail uid ' + row.uid +
        ' route ' + row.route + ' (index ' + row.routeIndex + ')' +
        ' arc ' + row.arc.toFixed(6) + ' m / ' + row.routeLengthM.toFixed(6) +
        ' m = ' + fraction.toFixed(9) +
        ' -> measured ' + layoutId + ' arc ' + sampleArc.toFixed(6) +
        ' m (sample ' + hit.index + ' of ' + samples.length + ')' +
        '; lateral ' + retailLateral.toFixed(6) + ' m ' +
        (clamped ? 'clamped to ' + appliedLateral.toFixed(6) : 'kept') +
        ' (band +/-' + band.halfWidthMetres.toFixed(6) + ' m from ' + band.source + ')' +
        '; rule normalized-retail-arc-fraction + banded-lateral'
    });
  }

  return {
    schema: RETAIL_PLACEMENT_SCHEMA,
    mapId,
    source: 'retail pickup placement for ' + mapId +
      ' on measured layout ' + layoutId +
      ' (' + measuredLengthText + ' m, band +/-' +
      (band ? band.halfWidthMetres.toFixed(6) : 'n/a') + ' m); ' +
      'rule normalized-retail-arc-fraction + banded-lateral; ' +
      'retail routes from probes/powerups/data/pickup-routes.json; ' +
      'not a physical projection (the measured layout is a sub-course of the retail route)',
    pickups,
    unsupported
  };
}
